<div class="pricing-workspace">
<section class="admin-page-head"><div><p class="admin-kicker">PRECIOS</p><h1>Precios comerciales</h1><p>Define cuánto se cobra al cotizar: una variante puede tener distintos precios por sucursal, lista y vigencia.</p></div><div class="admin-head-actions"><?php if($capabilities['prices.create']??false):?><a class="admin-primary-button" data-admin-form-link href="/admin/prices/create<?= $branchId!==null?'?branch_id='.e($branchId):'' ?>">+ Nuevo precio</a><?php endif?><a class="admin-secondary-button" data-admin-form-link href="/admin/prices/calculate">Calcular</a></div></section>
<section class="admin-panel pricing-filters"><header><h2>Buscar precios</h2><p>Consulta los importes y su vigencia por producto, sucursal o lista comercial.</p></header><form class="pricing-filter-grid" method="get" action="/admin/prices"><label class="admin-field"><span>Buscar</span><input type="search" name="q" maxlength="120" value="<?= e($q) ?>" placeholder="Producto, variante o SKU"></label><label class="admin-field"><span>Sucursal</span><select name="branch_id"><?php if($allBranches??false):?><option value="">Todas las sucursales</option><?php endif?><?php foreach($branches as$b):?><option value="<?= e($b['id']) ?>" <?= $branchId===(int)$b['id']?'selected':'' ?>><?= e($b['name']) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Lista</span><select name="list_id"><option value="">Todas</option><?php foreach($lists as$l):?><option value="<?= e($l['id']) ?>" <?= $listId===(int)$l['id']?'selected':'' ?>><?= e($l['name']) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Estado</span><select name="status"><option value="all">Todos</option><option value="active" <?= $status==='active'?'selected':'' ?>>Activos</option><option value="inactive" <?= $status==='inactive'?'selected':'' ?>>Inactivos</option></select></label><div class="pricing-filter-actions"><button class="admin-secondary-button">Aplicar filtros</button><?php if($q!==''||$status!=='all'||$branchId!==null||$listId!==null):?><a class="pricing-text-link" href="/admin/prices">Limpiar</a><?php endif?></div></form></section>
<section class="admin-panel admin-table-panel pricing-directory"><header class="pricing-directory-heading"><div><h2>Precios registrados</h2><p>Importes en MXN, tratamiento de impuesto y periodo de vigencia.</p></div><span><?= e(count($page->items)) ?> en esta página</span></header><?php if($page->items===[]):?><div class="pricing-empty"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 3h8l10 10-8 8L3 11V3Zm4 4h.01M12 9v8m3-6c-3-3-7 1-3 2s0 5-3 2"/></svg><h3><?= ($q!==''||$status!=='all'||$listId!==null)?'Sin coincidencias':'Sin precios configurados' ?></h3><p><?= ($q!==''||$status!=='all'||$listId!==null)?'Prueba con otra variante, sucursal, lista o estado.':'Registra el importe confirmado para una variante. Un producto sin precio configurado no se presenta como $0.00.' ?></p><div class="pricing-empty-actions"><?php if($q!==''||$status!=='all'||$listId!==null):?><a class="admin-secondary-button" href="/admin/prices">Limpiar filtros</a><?php elseif($capabilities['prices.create']??false):?><a class="admin-primary-button" data-admin-form-link href="/admin/prices/create<?= $branchId!==null?'?branch_id='.e($branchId):'' ?>">Registrar primer precio</a><?php endif?></div></div><?php else:?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Variante</th><th>Sucursal / lista</th><th>Importe</th><th>Impuesto</th><th>Vigencia</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($page->items as$p):?><tr><td><div><strong><?= e($p['product_name']) ?></strong><small><?= e($p['sku'].' · '.$p['variant_name']) ?></small></div></td><td><div><?= e($p['branch_name']) ?><small><?= e($p['list_name']) ?></small></div></td><td><div><strong>$<?= e($p['amount']) ?> MXN</strong><small><?= (int)$p['tax_included']===1?'Impuesto incluido':'Impuesto no incluido' ?></small></div></td><td><?= e($p['tax_name']) ?></td><td><div><?= e($p['valid_from']) ?><small><?= e($p['valid_until']??'Sin fecha final') ?></small></div></td><td><span class="admin-status <?= (int)$p['is_active']===1?'is-active':'' ?>"><?= (int)$p['is_active']===1?'Activo':'Inactivo' ?></span></td><td class="admin-actions"><?php if($capabilities['prices.edit']??false):?><a class="admin-secondary-button" data-admin-form-link href="/admin/prices/edit?id=<?= e($p['id']) ?>">Editar</a><?php endif?><?php if($capabilities['prices.status']??false):?><form method="post" action="/admin/prices/status"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= e($p['id']) ?>"><input type="hidden" name="lock_version" value="<?= e($p['lock_version']) ?>"><input type="hidden" name="active" value="<?= (int)$p['is_active']===1?'0':'1' ?>"><button class="admin-quiet-button" data-confirm="¿Confirmas el cambio de estado?"><?= (int)$p['is_active']===1?'Desactivar':'Activar' ?></button></form><?php endif?></td></tr><?php endforeach?></tbody></table></div><?php endif?></section>

<?php if($page->offset||$page->hasMore):?><nav class="admin-pagination" aria-label="Páginas de precios"><?php if($page->offset):?><a href="/admin/prices?<?= e(http_build_query(['q'=>$q,'branch_id'=>$branchId,'list_id'=>$listId,'status'=>$status,'offset'=>max(0,$page->offset-$page->limit)])) ?>">Anterior</a><?php endif?><?php if($page->hasMore):?><a href="/admin/prices?<?= e(http_build_query(['q'=>$q,'branch_id'=>$branchId,'list_id'=>$listId,'status'=>$status,'offset'=>$page->offset+$page->limit])) ?>">Siguiente</a><?php endif?></nav><?php endif?></div>
